import React, { useState, useRef, useCallback } from 'react';
import Webcam from 'react-webcam';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const webcamRef = useRef(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const videoConstraints = {
    width: 1280,
    height: 720,
    facingMode: "user"
  };

  const handleCapture = useCallback(async () => {
    if (!webcamRef.current) return;

    setLoading(true);
    setMessage("⏳ Analyse en cours...");

    try {
      const imageSrc = webcamRef.current.getScreenshot();
      if (!imageSrc) {
        setMessage("❌ Impossible de capturer l'image");
        return;
      }

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data || response || {};

      console.log("🔍 RAW RESPONSE:", response);
      console.log("📊 DATA:", data);

      const name = String(data.student || data.student_name || data.name || "Inconnu");
      const confidence = (Number(data.confidence || 0) * 100).toFixed(1);

      if (data.success || name !== "Inconnu") {
        setMessage(`✅ ${name} - Confiance: ${confidence}%`);
      } else {
        setMessage(`⚠️ ${String(data.message || data.error || "Visage non reconnu")}`);
      }

    } catch (err) {
      const msg = err.response?.data?.error || err.message || "Erreur serveur";
      setMessage(`❌ ${String(msg)}`);
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, []);

  return (
    <div style={{ padding: '40px', maxWidth: '800px', margin: '0 auto', textAlign: 'center' }}>
      <h1 style={{ marginBottom: '30px' }}>📷 Reconnaissance Faciale</h1>

      <div style={{ 
        borderRadius: '16px', 
        overflow: 'hidden', 
        background: '#000', 
        marginBottom: '30px',
        boxShadow: '0 10px 40px rgba(0,0,0,0.4)'
      }}>
        <Webcam
          ref={webcamRef}
          audio={false}
          screenshotFormat="image/jpeg"
          videoConstraints={videoConstraints}
          style={{ width: '100%', height: 'auto' }}
        />
      </div>

      <button 
        onClick={handleCapture}
        disabled={loading}
        style={{
          padding: '16px 32px',
          fontSize: '18px',
          background: loading ? '#6b7280' : '#4F46E5',
          color: 'white',
          border: 'none',
          borderRadius: '10px',
          cursor: loading ? 'not-allowed' : 'pointer',
          marginBottom: '30px'
        }}
      >
        {loading ? '⏳ Traitement en cours...' : '🔍 Lancer le Scan'}
      </button>

      {message && (
        <div style={{
          padding: '20px',
          margin: '0 auto',
          maxWidth: '600px',
          borderRadius: '12px',
          fontSize: '20px',
          fontWeight: '500',
          background: message.includes('✅') ? '#DCFCE7' : '#FEE2E2',
          color: message.includes('✅') ? '#166534' : '#991B1B',
          border: message.includes('✅') ? '3px solid #86EFAC' : '3px solid #FECACA'
        }}>
          {message}
        </div>
      )}
    </div>
  );
};

export default CameraRecognition;
